import{_ as e,o,c as a,ai as r}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"决策实验室","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/decision-lab.md","filePath":"zh/guide/decision-lab.md"}'),n={name:"zh/guide/decision-lab.md"};function l(s,t,d,i,c,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="决策实验室" tabindex="-1">决策实验室 <a class="header-anchor" href="#决策实验室" aria-label="Permalink to &quot;决策实验室&quot;">​</a></h1><p><strong>决策实验室</strong>向决策模型提出关于某个情境的类型化问题，并展示每个答案背后的概率。</p><p><strong>侧边栏位置：</strong> 决策实验室（在缓存实验室下方） <strong>路由：</strong> <code>/decision-lab</code><strong>加入版本：</strong> v0.7.0（2026 年 10 月） <strong>需要：</strong> Ollama 0.35.1 或更新版本，以及一个决策模型（<code>nimble</code>、<code>tev1</code>、<code>clef-flash</code> 或 <code>clef</code>）</p><h2 id="有什么用" tabindex="-1">有什么用？ <a class="header-anchor" href="#有什么用" aria-label="Permalink to &quot;有什么用？&quot;">​</a></h2><p>决策模型不生成文本。你给它一个<strong>状态</strong>（一张工单、一条消息、一行日志、一份文档）和一个或多个<strong>问题</strong>，它返回：</p><table tabindex="0"><thead><tr><th>问题类型</th><th>返回内容</th></tr></thead><tbody><tr><td><strong>选择</strong></td><td>选中的候选项、<em>每个</em>候选项的概率，以及置信度</td></tr><tr><td><strong>是 / 否概率</strong></td><td>条件成立的单一概率</td></tr><tr><td><strong>刻度评分</strong></td><td>在你的有序刻度上的期望位置、每一档的概率，以及置信度</td></tr></tbody></table><p>这些概率是模型自身在候选项上的输出分布，而不是从一句话里解析出来的数字。这正是它们值得看的原因：问聊天模型&quot;这紧急吗？&quot;，它答<em>是</em>；问决策模型，它答 <em>0.99</em>，遇到模棱两可的工单则答 <em>0.55</em>，差别一目了然。</p><p>Ollama 通过 <code>/v1/systemone</code>（0.35.1 加入）提供这类模型。它们把 <code>decision</code> 作为<strong>唯一</strong>能力上报，所以 LLMxRay 把它们排除在所有对话和嵌入选择器之外，只在这里列出。给它们发送对话请求并不会干净地报错，而是回复自己 schema 的碎片，这正是需要过滤的原因。</p><h2 id="使用页面" tabindex="-1">使用页面 <a class="header-anchor" href="#使用页面" aria-label="Permalink to &quot;使用页面&quot;">​</a></h2><ol><li>选择一个决策模型。如果没有安装，在模型页拉取一个；<code>tev1:0.8b</code> 最小。</li><li>描述<strong>状态</strong>。所有问题都针对这一段文字。</li><li>编辑<strong>问题</strong>。每个问题有答案键（结果以此为键返回）、类型、指令，选择和评分类型还需要候选项列表： <ul><li><strong>选择</strong>：每行一个，格式为 <code>名称: 描述</code>。</li><li><strong>评分</strong>：每行一个，从低到高。顺序<em>就是</em>刻度。</li><li>Ollama 每次请求接受 2 到 26 个候选项、1 到 64 个问题；超出范围时页面会在发送前提示。</li></ul></li><li><strong>判断</strong>。答案以条形图显示在右侧，选中项高亮，并附输入、输出 token 数和往返时间。</li></ol><p>页面打开时自带一个完整示例：一张客服工单，以三种方式提问，每种类型一个问题。这正是验证 Ollama 0.40.3 时实际运行过的请求。</p><h2 id="解读答案" tabindex="-1">解读答案 <a class="header-anchor" href="#解读答案" aria-label="Permalink to &quot;解读答案&quot;">​</a></h2><ul><li><strong>选择</strong>：条形按概率排序。高亮的是模型的选择。置信度是模型自己报告的数字。</li><li><strong>是 / 否</strong>：显示为<em>是</em>和<em>否</em>两条，总和为 1。</li><li><strong>评分</strong>：条形保持刻度顺序，因为位置即含义。高亮的是概率最高的一档。<em>评分</em>数值是期望位置（按概率加权），因此可能落在两档之间：四档刻度上的 2.37 意味着&quot;重大，偏向完全中断&quot;。</li></ul><h2 id="此页面不做什么" tabindex="-1">此页面不做什么 <a class="header-anchor" href="#此页面不做什么" aria-label="Permalink to &quot;此页面不做什么&quot;">​</a></h2><p>它不流式输出（该端点从不流式），不保存历史，也暂不发送图片，尽管 <code>clef</code> 和 <code>clef-flash</code> 支持。它只是一个观察决策模型真实返回内容的观测台，仅此而已。</p>',15)])])}const u=e(n,[["render",l]]);export{m as __pageData,u as default};
